//! Historical nearest-station catchments and fixed gravity distribution, versioned independently.
use crate::{editor_support::*,value::Value as V,legacy::{self,distance}};
use std::{collections::HashMap,rc::Rc,cell::RefCell};
const FIELDS:[&str;5]=["people","jobs","shops","industry","leisure"];
const PROFILES:[(&str,&str,f64,f64);3]=[("work","jobs",0.52,14.0),("shopping","shops",0.16,5.0),("leisure","leisure",0.12,10.0)];
struct Gravity{zone:HashMap<String,usize>,weights:Vec<Vec<(Vec<f64>,f64)>>}
impl Gravity{
 fn new(city:&V)->Self{let mut zones:Vec<V>=vec![];let mut indices=HashMap::new();let mut zone=HashMap::new();for c in city.get("cells").array(){let key=format!("{}:{}",(c.num("x")/80.0).floor(),(c.num("y")/80.0).floor());let i=*indices.entry(key).or_insert_with(||{zones.push(obj(&[("x",n(0.0)),("y",n(0.0)),("count",n(0.0)),("jobs",n(0.0)),("shops",n(0.0)),("leisure",n(0.0))]));zones.len()-1});zone.insert(jsstring(c.get("id")),i);for k in ["x","y","jobs","shops","leisure"]{legacy::add(&mut zones[i],k,c.num(k));}legacy::add(&mut zones[i],"count",1.0);}for z in &mut zones{z.set("x",n(z.num("x")/z.num("count")));z.set("y",n(z.num("y")/z.num("count")));}let weights=zones.iter().map(|origin|PROFILES.iter().map(|(_,field,_,decay)|{let targets=zones.iter().map(|z|crate::demand::raw_exp(-distance(origin,z)/decay)).collect::<Vec<_>>();let total=zones.iter().zip(&targets).map(|(z,w)|z.num(field)*w).sum();(targets,total)}).collect()).collect();Self{zone,weights}}
 fn trips(&self,o:&V,d:&V,p:usize)->f64{let Some(&a)=self.zone.get(&jsstring(o.get("id")))else{return 0.0;};let Some(&b)=self.zone.get(&jsstring(d.get("id")))else{return 0.0;};let(targets,total)=&self.weights[a][p];if *total==0.0{0.0}else{o.num("people")*PROFILES[p].2*d.num(PROFILES[p].1)*targets[b]/total}}
}
thread_local!{static GRAVITY:RefCell<Option<Rc<Gravity>>>=const{RefCell::new(None)};}
fn gravity(city:&V)->Rc<Gravity>{GRAVITY.with(|slot|{if slot.borrow().is_none(){*slot.borrow_mut()=Some(Rc::new(Gravity::new(city)));}slot.borrow().as_ref().unwrap().clone()})}
fn mapping(catchment:&V)->HashMap<String,V>{catchment.get("mapping").array().iter().map(|row|(jsstring(&row.array()[0]),row.array()[1].clone())).collect()}
fn assign(s:&V,city:&V)->V{let ids=unique(&s.get("services").array().iter().flat_map(|l|l.get("callStops").array().iter().chain(if l.get("callStops").truth(){&[][..]}else{l.get("stops").array()}).cloned().collect::<Vec<_>>()).collect::<Vec<_>>());let served=ids.iter().map(|id|&s.get("nodes").array()[id.n()as usize]).collect::<Vec<_>>();let mut stations=V::Object(served.iter().map(|s|(jsstring(s.get("id")),obj(&[("people",n(0.0)),("jobs",n(0.0)),("shops",n(0.0)),("industry",n(0.0)),("leisure",n(0.0)),("walk",n(0.0)),("cells",n(0.0))]))).collect());let mut entries=vec![];let mut covered=0.0;for c in city.get("cells").array(){let(mut closest,mut best)=(None,0.8);for node in &served{let d=distance(c,node)*1.25;if d<best{best=d;closest=Some(*node);}}if let Some(node)=closest{entries.push(arr(vec![c.get("id").clone(),obj(&[("id",node.get("id").clone()),("walk",n(best))])]));let st=stations.get_mut(&jsstring(node.get("id")));for field in FIELDS{legacy::add(st,field,c.num(field));}legacy::add(st,"walk",best*c.num("people"));legacy::add(st,"cells",1.0);covered+=c.num("people");}}for(_,st)in stations.entries_mut(){st.set("walk",n(if st.num("people")!=0.0{st.num("walk")/st.num("people")}else{0.0}));}obj(&[("stations",stations),("mapping",arr(entries)),("covered",n(covered)),("total",city.get("totals").get("people").clone())])}
fn visit(city:&V,map:&HashMap<String,V>,mut visitor:impl FnMut(&V,&V,usize,bool,f64)){let demand=gravity(city);let covered=city.get("cells").array().iter().filter(|c|map.contains_key(&jsstring(c.get("id")))).collect::<Vec<_>>();for o in &covered{if o.num("people")==0.0{continue;}for d in &covered{if eq(o.get("id"),d.get("id")){continue;}for p in 0..3{let amount=demand.trips(o,d,p);if amount>0.0{visitor(o,d,p,false,amount);visitor(d,o,p,true,amount);}}}}}
fn evaluate(s:&V,city:&V)->V{let catchment=assign(s,city);let map=mapping(&catchment);let total=city.get("totals").num("people")*1.6;let mut uncovered=total;let mut purpose=obj(&[("work",n(0.0)),("shopping",n(0.0)),("leisure",n(0.0))]);let mut groups:Vec<V>=vec![];let mut lookup=HashMap::new();if !s.get("services").array().is_empty(){visit(city,&map,|o,d,p,back,people|{uncovered-=people;let a=&map[&jsstring(o.get("id"))];let b=&map[&jsstring(d.get("id"))];if eq(a.get("id"),b.get("id")){return;}let key=(a.num("id")as usize,b.num("id")as usize,p,back);let ix=*lookup.entry(key).or_insert_with(||{groups.push(obj(&[("from",a.get("id").clone()),("to",b.get("id").clone()),("purpose",text(PROFILES[p].0)),("back",boolean(back)),("people",n(0.0)),("walk",n(0.0))]));groups.len()-1});legacy::add(&mut groups[ix],"people",people);legacy::add(&mut groups[ix],"walk",(a.num("walk")+b.num("walk"))*people);});}
    let adj=legacy::graph(s,&V::Missing);let router=legacy::Router::new(s,&adj,true);let mut paths=HashMap::new();let mut flows=vec![];for g in groups{let from=g.num("from")as usize;let ps=paths.entry(from).or_insert_with(||router.paths(from,0.045));let path=&ps[g.num("to")as usize];if path.get("edges").array().is_empty(){continue;}let km=distance(&s.get("nodes").array()[from],&s.get("nodes").array()[g.num("to")as usize]);let walk=g.num("walk")/g.num("people")*1000.0/80.0;let road=8.0+km/23.0*60.0*1.22;let rail=path.num("minutes")+walk;let share=0.93/(1.0+crate::demand::raw_exp(((rail+path.num("fare")*0.045-road-8.0)/8.0).clamp(-40.0,40.0)));let trips=g.num("people")*share;if trips<0.1{continue;}legacy::add(&mut purpose,g.get("purpose").text(),trips);flows.push(obj(&[("from",g.get("from").clone()),("to",g.get("to").clone()),("trips",n(trips)),("demandTrips",n(trips)),("path",path.clone()),("road",n(road)),("rail",n(rail)),("purpose",g.get("purpose").clone()),("back",g.get("back").clone()),("walk",n(walk)),("population",g.get("people").clone())]));}
    let(mut track_flow,mut service_flow)=(obj(&[]),obj(&[]));for f in &flows{for e in f.get("path").get("edges").array(){let ids=if e.get("tracks").truth(){e.get("tracks").array().to_vec()}else{vec![e.get("track").clone()]};for id in ids{legacy::add(&mut track_flow,id.text(),f.num("trips"));}}}let loads=legacy::track_load(s,&track_flow);let(mut riders,mut unserved)=(0.0,0.0);for f in &mut flows{let ratio=f.get("path").get("edges").array().iter().map(|e|1.0/loads.zero(e.get("track").text()).max(1.0)).fold(1.0,f64::min);f.set("trips",n(f.num("trips")*ratio));riders+=f.num("trips");unserved+=f.num("demandTrips")-f.num("trips");for id in unique(&f.get("path").get("edges").array().iter().map(|e|e.get("service").clone()).collect::<Vec<_>>()){legacy::add(&mut service_flow,id.text(),f.num("trips"));}}
    let mut out=obj(&[("city",boolean(true)),("flows",arr(flows)),("trackFlow",track_flow),("trackLoad",loads),("serviceFlow",service_flow),("riders",n(riders)),("unserved",n(unserved)),("totalTrips",n(total)),("uncoveredTrips",n(uncovered)),("purposeTotals",purpose),("catchment",catchment),("population",city.get("totals").get("people").clone()),("jobs",city.get("totals").get("jobs").clone())]);if s.get("services").array().is_empty(){del(&mut out,"trackLoad");out.set("trackLoad",obj(&[]));}out
}
pub(super) fn run(action:&str,s:&V,a:&V)->V{let city=crate::bootstrap::city("tokyo");match action{
 "cityAssign"=>assign(s,&city),"cityEvaluate"=>evaluate(s,&city),"cityProfiles"=>arr(PROFILES.iter().map(|(p,f,r,d)|obj(&[("purpose",text(p)),("rate",n(*r)),("field",text(f)),("decay",n(*d))])).collect()),
 "cityTrips"=>{let p=PROFILES.iter().position(|(p,_,_,_)|*p==a.get("profile").get("purpose").text()).unwrap_or(0);n(gravity(&city).trips(a.get("origin"),a.get("destination"),p))},
 "cityJourneys"=>{let map:HashMap<String,V>=a.get("mapping").array().iter().map(|row|(jsstring(&row.array()[0]),row.array()[1].clone())).collect();let covered=city.get("cells").array().iter().filter(|c|map.contains_key(&jsstring(c.get("id")))).collect::<Vec<_>>();let size=covered.len();let total=size*size*6;let mut cursor=a.zero("cursor")as usize;let count=(a.zero("count")as usize).clamp(1,256);let demand=gravity(&city);let mut rows=vec![];
  while cursor<total&&rows.len()<count{let index=cursor;cursor+=1;let pair=index/6;let o=covered[pair/size];let d=covered[pair%size];let p=(index%6)/2;let back=index%2==1;if o.num("people")==0.0||eq(o.get("id"),d.get("id")){continue;}let people=demand.trips(o,d,p);if people<=0.0{continue;}let(origin,destination)=if back{(d,o)}else{(o,d)};rows.push(obj(&[("origin",origin.get("id").clone()),("destination",destination.get("id").clone()),("purpose",text(PROFILES[p].0)),("back",boolean(back)),("people",n(people))]));}
  obj(&[("rows",arr(rows)),("next",if cursor<total{n(cursor as f64)}else{V::Null})])},
 _=>obj(&[("error",text("UNKNOWN_LEGACY_CITY_QUERY"))])}}
